import { describe, test, expect } from 'bun:test';
import { sha384 } from './sha384.js';
import { sha512 } from './sha512.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha512 = sha512.factory(_ba, _utf8);
const _sha = sha384.factory(_sha512);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));
const haxToBitsBA = (hexStr, bitLen) => {
    if (bitLen === 0) return [];
    const bytes = _hex.toBytes(hexStr);
    const ba = _ba.ui8_to_ba(bytes);
    return _ba.clamp(ba, bitLen);
};

describe('sha384 module', () => {

    test('module metadata', () => {
        expect(sha384.name).toBe('sha384');
        expect(typeof sha384.factory).toBe('function');
    });

    describe('FIPS-180 vectors', () => {
        test('empty string', () => {
            expect(toHex(_sha.hash('')))
                .toBe('38b060a751ac96384cd9327eb1b1e36a21fdb71114be07434c0cc7bf63f6e1da274edebfe76f65fbd51ad2f14898b95b');
        });

        test('"abc"', () => {
            expect(toHex(_sha.hash('abc')))
                .toBe('cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7');
        });
    });

    describe('streaming', () => {
        test('digest is 384 bits (12 x 32-bit words)', () => {
            const out = _sha.hash('hello');
            expect(out.length).toBe(12);
        });

        test('chunked update matches one-shot', () => {
            const oneShot = toHex(_sha.hash('FIPS-180 sha384 streaming check'));
            const h = new _sha.fn();
            h.update('FIPS-180 ');
            h.update('sha384 ');
            h.update('streaming check');
            expect(toHex(h.finalize())).toBe(oneShot);
        });
    });
});

