describe('sha384 - ACVP SHA2-384-1.0', () => {

    describe('AFT vectors (testGroup 1, sub-sampled)', () => {
        test.each(SHA384_AFT)('tcId=$tc (len=$len bits)', (v) => {
            const ba = haxToBitsBA(v.msg, v.len);
            expect(_ba.bitLength(ba)).toBe(v.len);
            expect(toHex(_sha.hash(ba))).toBe(v.md.toLowerCase());
        });
    });

    describe('MCT (testGroup 2, standard)', () => {
        test('100 outer iterations match resultsArray byte-exact', () => {
            const seedBytes = _hex.toBytes(SHA384_MCT_SEED_HEX);
            expect(seedBytes.length * 8).toBe(SHA384_MCT_SEED_LEN);

            const concat = (...arrs) => {
                let n = 0; for (const a of arrs) n += a.length;
                const out = new Uint8Array(n);
                let o = 0; for (const a of arrs) { out.set(a, o); o += a.length; }
                return out;
            };

            let SEED = seedBytes; // 48 bytes
            for (let j = 0; j < 100; j++) {
                let A = SEED, B = SEED, C = SEED;
                for (let i = 0; i < 1000; i++) {
                    const MSG = concat(A, B, C); // 144 bytes = 1152 bits
                    const MD = _ba.ba_to_ui8(_sha.hash(_ba.ui8_to_ba(MSG)));
                    A = B; B = C; C = MD;
                }
                SEED = C;
                expect(_hex.fromBytes(SEED)).toBe(SHA384_MCT_EXPECTED[j].toLowerCase());
            }
        }, 120_000);
    });

    // ── Iteration H1 - Large Data Test (LDT, ACVP-SHA2-384-1.0 tg=3) ────────
    const RUN_LDT = process.env.CRYPTO_FULL === '1';
    (RUN_LDT ? describe : describe.skip)('ACVP-SHA2-384-1.0 LDT (1 GiB) - CRYPTO_FULL only', () => {
        test('tcId=1026 - 1 GiB of "3d04a3d3c6a52e47" repeating', () => {
            const content = _hex.toBytes('3d04a3d3c6a52e47');
            const fullLengthBytes = 8589934592 / 8;
            const CHUNK = 1024 * 1024;
            const chunk = new Uint8Array(CHUNK);
            for (let i = 0; i < CHUNK; i += content.length) chunk.set(content, i);
            const chunkBa = _ba.ui8_to_ba(chunk);
            const h = new _sha.fn();
            const iter = fullLengthBytes / CHUNK;
            for (let i = 0; i < iter; i++) h.update(chunkBa);
            expect(toHex(h.finalize())).toBe(
                'f806623d6ca0fae48554290b3385892677d2b5ab16e73826449e7891cc5fc97ea608c598c7dfe12600e08d3fead3085b'
            );
        }, 10 * 60 * 1000);
    });

});
